/**
 * Embedded 8x13 bitmap font (X11 Base-14 "fixed", X.Org font-misc 8x13.bdf,
 * ISO10646-1 build, public domain). Glyph bitmaps are the same ones OMP's
 * native snapcompact renderer uses for its `8x13` shapes.
 *
 * Layout: sorted entries of 15 bytes each: 2-byte big-endian Unicode code
 * point + 13 rows, one byte per row, MSB = leftmost pixel. Baseline is row 11
 * (ascent 11, descent 2).
 *
 * Generated by scripts/gen-font.mjs from 8x13.bdf - do not edit by hand.
 */
const FONT_WIDTH = 8;
const FONT_ROWS = 13;
const FONT_ASCENT = 11;
const FONT_DESCENT = 2;

const GLYPH_DATA = "";

const raw = Buffer.from(GLYPH_DATA, "base64");
const glyphTable = new Map<number, number>(); // code -> 13-byte row
for (let i = 0; i < raw.length; i += 15) {
  glyphTable.set(raw.readUInt16BE(i), i);
}

/** Row bytes for one code point, or undefined when the font has no glyph. */
export function fontRows(code: number): number[] | undefined {
  const at = glyphTable.get(code);
  if (at === undefined) return undefined;
  const out: number[] = [];
  for (let r = 0; r < FONT_ROWS; r++) out.push(raw[at + 2 + r]);
  return out;
}

/** True when the font can render the code point (an empty space glyph counts). */
export function fontSupports(code: number): boolean {
  return glyphTable.has(code);
}

/** The subset of `text` the embedded 8x13 font can render. */
export function supportedChars(text: string): string {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const ch of text) {
    if (seen.has(ch)) continue;
    seen.add(ch);
    const cp = ch.codePointAt(0);
    if (cp !== undefined && fontSupports(cp)) out.push(ch);
  }
  return out.join("");
}

export const FONT_METRICS = { width: FONT_WIDTH, rows: FONT_ROWS, ascent: FONT_ASCENT, descent: FONT_DESCENT };
